pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address owner, address recipient, uint256 amount) public {
        vm.assume(owner != address(0) && recipient != address(0));
        vm.assume(owner != recipient);
        vm.assume(amount > 0);
        // re-deploy with the fuzzed owner
        c = new C(owner);
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        uint256 recipientBalanceBefore = recipient.balance;
        vm.prank(owner);
        bool ok = true;
        try c.withdrawAll(recipient) {} catch { ok = false; }
        assertTrue(ok);
        uint256 recipientBalanceAfter = recipient.balance;
        assertTrue(recipientBalanceAfter == recipientBalanceBefore + balanceBefore);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address recipient, uint256 amount) public {
        // Admissible domain: amount > 0 so contract has balance to transfer;
        // recipient != owner to distinguish correct from buggy behavior.
        vm.assume(amount > 0);
        vm.assume(recipient != address(this));

        // Fund contract and record sender's initial balance
        vm.deal(address(this), amount);
        vm.prank(address(this));
        (bool funded,) = address(c).call{value: amount}("");
        require(funded, "funding contract failed");

        uint256 recipientBefore = recipient.balance;

        // Owner calls withdrawAll with fuzzed recipient
        vm.prank(address(this));
        c.withdrawAll(recipient);

        uint256 recipientAfter = recipient.balance;

        // Rule: recipient's balance must increase by the transferred amount (amount).
        // Bug breaks this when recipient != owner, sending balance to owner instead.
        assertEq(recipientAfter - recipientBefore, amount);
    }
}

